import{_ as i,c as a,o as s,j as o,Y as n,t as r}from"./chunks/framework.BNTND4LZ.js";const m=JSON.parse('{"title":"git-bugreport | x-cmd man (git man1) | Collect information for user to file a bug report","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-bugreport - Collect information for user to file a bug report","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-bugreport | x-cmd man (git man1) | Collect information for user to file a bug report"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-bugreport - Collect information for user to file a bug report"}]]},"headers":[],"params":{"isMan":true,"man":"git-bugreport","category":"git man1","desc":"Collect information for user to file a bug report"},"relativePath":"git/man1/git-bugreport.md","filePath":"git/man1/[man].md"}'),l={name:"git/man1/git-bugreport.md"},p={class:"visually-hidden"};function h(e,t,g,d,u,c){return s(),a("div",null,[o("h1",p,r(e.$params.man),1),t[0]||(t[0]=n(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-bugreport - Collect information for user to file a bug report</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bugreport</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [(-o </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --output-directory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">path</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] [(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">suffix) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">format</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[--diagnose[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mode</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Captures information about the user&#39;s machine, Git client, and repository state, as well as a form requesting information about the behavior the user observed, into a single text file which the user can then share, for example to the Git mailing list, in order to report an observed bug.</p><p>The following information is requested from the user:</p><blockquote><p>·</p><p>Reproduction steps</p></blockquote><blockquote><p>·</p><p>Expected behavior</p></blockquote><blockquote><p>·</p><p>Actual behavior</p></blockquote><p>The following information is captured automatically:</p><blockquote><p>·</p><p><em>git version --build-options</em></p></blockquote><blockquote><p>·</p><p>uname sysname, release, version, and machine strings</p></blockquote><blockquote><p>·</p><p>Compiler-specific info string</p></blockquote><blockquote><p>·</p><p>A list of enabled hooks</p></blockquote><blockquote><p>·</p><p>$SHELL</p></blockquote><p>Additional information may be gathered into a separate zip archive using the <strong>--diagnose</strong> option, and can be attached alongside the bugreport document to provide additional context to readers.</p><p>This tool is invoked via the typical Git setup process, which means that in some cases, it might not be able to launch - for example, if a relevant config file is unreadable. In this kind of scenario, it may be helpful to manually gather the kind of information listed above when manually asking for help.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-o &lt;path&gt;, --output-directory &lt;path&gt;</p><blockquote><p>Place the resulting bug report file in <strong>&lt;path&gt;</strong> instead of the current directory.</p></blockquote><p>-s &lt;format&gt;, --suffix &lt;format&gt;</p><blockquote><p>Specify an alternate suffix for the bugreport name, to create a file named <em>git-bugreport-&lt;formatted suffix&gt;</em>. This should take the form of a strftime(3) format string; the current local time will be used.</p></blockquote><p>--no-diagnose, --diagnose[=&lt;mode&gt;]</p><blockquote><p>Create a zip archive of supplemental information about the user&#39;s machine, Git client, and repository state. The archive is written to the same output directory as the bug report and is named <em>git-diagnostics-&lt;formatted suffix&gt;</em>.</p><p>Without <strong>mode</strong> specified, the diagnostic archive will contain the default set of statistics reported by <strong>git diagnose</strong>. An optional <strong>mode</strong> value may be specified to change which information is included in the archive. See <strong>git-diagnose</strong>(1) for the list of valid values for <strong>mode</strong> and details about their usage.</p></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,27))])}const f=i(l,[["render",h]]);export{m as __pageData,f as default};
